using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"), Description("Returns the current application configuration")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/version", Name = "App Version",
        MimeType = "text/plain"), Description("Returns the application version string")]
    public static string GetVersion() => "1.0.0";
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Retrieves a configuration value by key name")]
    public static string GetConfigValue(
        [Description("The configuration key to look up")] string key)
    {
        var settings = new Dictionary<string, string>
        {
            ["db_host"] = "db.example.com",
            ["db_port"] = "5432",
            ["cache_ttl"] = "300",
            ["log_level"] = "Information"
        };

        return settings.TryGetValue(key, out var value)
            ? value
            : $"Key '{key}' not found. Available keys: {string.Join(", ", settings.Keys)}";
    }
}

